package com.careflow.ai.clinical;
import com.careflow.common.exception.BusinessException;import com.fasterxml.jackson.databind.*;import jakarta.servlet.http.HttpServletRequest;import java.time.*;import java.text.Normalizer;import java.util.*;import java.util.stream.*;
/** Local extractive assistance. Source text remains data and is never interpreted as instructions. */
public class ClinicalEngine {
    public static final String MODEL="careflow-local-evidence-v1";private final ClinicalStore store;private final AiAccess access;private final ObjectMapper json;private final boolean synthetic;
    public ClinicalEngine(ClinicalStore store,AiAccess access,ObjectMapper json,boolean synthetic){this.store=store;this.access=access;this.json=json;this.synthetic=synthetic;}
    public static Set<String> tokens(String s){String n=Normalizer.normalize(s.toLowerCase(Locale.ROOT),Normalizer.Form.NFD).replaceAll("\\p{M}","").replace('đ','d');return Arrays.stream(n.split("[^a-z0-9]+")).filter(t->t.length()>2&&!Set.of("cac","cho","cua","voi","benh","nhan","huong","dan","phac","dieu","tri","goi","theo","thong","tin","thieu").contains(t)).limit(500).collect(Collectors.toSet());}
    public JsonNode ask(UUID consultation,String question,UUID parent,HttpServletRequest request){
        if(question==null||question.isBlank()||question.length()>2000)throw new BusinessException(400,"Câu hỏi cần có1–2000ký tự");var actor=access.doctor(request);var context=access.context(consultation,actor);if(parent!=null)store.read(parent,actor.id(),consultation);
        var all=store.eligibleSources(context.department(),synthetic).stream().filter(s->s.status().equals("APPROVED")&&s.department().equals(context.department())&&(synthetic||!s.synthetic())).toList();if(all.isEmpty())throw new BusinessException(503,"Chưa có nguồn chuyên môn được duyệt cho khoa này");
        Set<String> query=tokens(question),facts=tokens(context.facts().path("symptoms").asText()+" "+context.facts().path("diagnosis").asText());
        record Hit(ClinicalStore.Source source,double score){};
        var ranked=all.stream().map(s->{var terms=tokens(s.title()+" "+s.content());long explicit=query.stream().filter(terms::contains).count();long contextual=facts.stream().filter(terms::contains).count();return new Hit(s,explicit*2.0+contextual*.25);}).filter(h->h.score()>0).sorted(Comparator.comparingDouble(Hit::score).reversed().thenComparing(h->h.source().id())).limit(3).toList();
        UUID id=UUID.randomUUID();var out=json.createObjectNode();out.put("interactionId",id.toString()).put("consultationId",consultation.toString()).put("mode",ranked.isEmpty()?"INSUFFICIENT_EVIDENCE":"LOCAL_EVIDENCE_RETRIEVAL").put("summary",ranked.isEmpty()?"Chưa tìm thấy căn cứ phù hợp trong các nguồn đã duyệt. Hãy bổ sung thông tin hoặc tra cứu chuyên môn.":"Các đoạn hướng dẫn đã duyệt dưới đây phù hợp từ khóa và ngữ cảnh. Đây là trích dẫn để bác sĩ đối chiếu, không phải kết luận tự động.").put("generatedAt",Instant.now().toString()).put("disclaimer","Bác sĩ quyết định chuyên môn; hệ thống không tự ghi toa hoặc chỉ định.");
        var citations=out.putArray("citations");var suggestions=out.putArray("suggestions");var warnings=out.putArray("warnings");var missing=out.putArray("missingInformation");for(String field:List.of("symptoms","bloodPressure","temperature","allergyNotes"))if(!context.facts().hasNonNull(field)||context.facts().path(field).asText().isBlank())missing.add("Thiếu dữ liệu: "+field);
        for(var h:ranked){var s=h.source();citations.addObject().put("sourceId",s.id().toString()).put("title",s.title()).put("revision",s.revision()).put("url",s.url()).put("contentHash",s.hash()).put("reviewedAt",s.reviewedAt().toString()).put("quote",s.content()).put("synthetic",s.synthetic());suggestions.addObject().put("type","TREATMENT_REFERRAL").put("text",s.title()+" — phiên bản "+s.revision());if(s.synthetic())warnings.add("NGUỒN TỔNG HỢP KIỂM THỬ — không dùng quyết định chuyên môn.");}
        out.putObject("model").put("provider","SELF_HOSTED").put("name",MODEL).put("version","1.0");out.put("contextHash",com.careflow.ai.voice.VoiceRemoteClient.sha(context.facts().toString()));
        access.context(consultation,actor);var envelope=json.createObjectNode().put("question",question);envelope.set("response",out);store.save(id,actor.id(),consultation,parent,out.path("contextHash").asText(),envelope,MODEL);return out;
    }
    public JsonNode read(UUID id,HttpServletRequest request){var actor=access.doctor(request);UUID consultation=store.consultation(id,actor.id());access.context(consultation,actor);return store.read(id,actor.id(),consultation).path("response");}
    public List<JsonNode> history(UUID consultation,HttpServletRequest request){var actor=access.doctor(request);access.context(consultation,actor);return store.history(actor.id(),consultation).stream().map(id->store.read(id,actor.id(),consultation)).toList();}
}
